tool.command:
mkdir out ;
## Rename all input files to correct extensions mv "$scan" "$scan.element_identifier" ; mv "$predicted" "$predicted.element_identifier" ;
#set $options = ""
#if $anisotropic: #set $options = $options + " --anisotropic " #end if #if $mosaicFit: #set $options = $options + " --fit-mosaicity " #end if #if $mosaicRadial: #set $options = $options + " --mosaicity-radial " #end if #if $spherical: #set $options = $options + " --shape-spherical " #end if #if $normalized: #set $options = $options + " --shape-fit-normalized " #end if #if $matrix: #set $options = $options + " --matrix-free " #end if #if $matrixFP: #set $options = $options + " --matrix-free-fp-target " + str($matrixFP) + " " #end if #if $staticMaskFile: #set $options = $options + " --static-mask-file " + str($staticMaskFile) + " " #end if
python -m subhkl.io.parser integrator "$scan.element_identifier" $instrument "$predicted.element_identifier" out/integrator.h5 --sigmas $sigma --nominal-sigma $nominalSigma --mosaic-bound-mrad $mosaicMrad --shape-fit-min-snr $snr --matrix-free-profile $matrixProfile --rel-border-width $relBorder --chunk-size $chunk --region-growth-minimum-sigma $sigma --create-visualizations --show-progress $options ;
ls ;
